// Generated by `dart run drift_dev make-migrations`, then filled in. Rerun the
// command after each schema change; it adds the new versions to `generated/`.
// ignore_for_file: unused_local_variable, unused_import
import 'dart:convert';
import 'dart:io';

import 'package:drift/drift.dart';
import 'package:drift/native.dart';
import 'package:drift_dev/api/migrations_native.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:travel_planner/data/attachment_store.dart';
import 'package:travel_planner/data/db.dart';
import 'package:travel_planner/data/doc_migrations.dart';
import 'package:travel_planner/data/repository.dart';
import 'package:travel_planner/domain/demo.dart';

import 'generated/schema.dart';
import 'generated/schema_v1.dart' as v1;
import 'generated/schema_v2.dart' as v2;

void main() {
  driftRuntimeOptions.dontWarnAboutMultipleDatabases = true;
  late SchemaVerifier verifier;

  setUpAll(() {
    verifier = SchemaVerifier(GeneratedHelper());
  });

  group('simple database migrations', () {
    // Every possible upgrade path, checked against the exported schemas.
    const versions = GeneratedHelper.versions;
    for (final (i, fromVersion) in versions.indexed) {
      group('from $fromVersion', () {
        for (final toVersion in versions.skip(i + 1)) {
          test('to $toVersion', () async {
            final schema = await verifier.schemaAt(fromVersion);
            final db = AppDatabase(schema.newConnection());
            await verifier.migrateAndValidate(db, toVersion);
            await db.close();
          });
        }
      });
    }
  });

  test('migration from v1 to v2 keeps the rows; opening brings them to the current doc version', () async {
    const oldDocsData = [
      v1.DocsData(id: 't1', tripId: 't1', type: 'trip', json: '{"id":"t1"}', updatedAt: 10),
      v1.DocsData(id: 'i1', tripId: 't1', type: 'item', json: '{"id":"i1"}', updatedAt: 20),
    ];
    // The schema step sets doc version 1, beforeOpen then runs the doc steps
    // (which leave trips and items as they are).
    final expectedNewDocsData = [
      v2.DocsData(id: 't1', tripId: 't1', type: 'trip', json: '{"id":"t1"}', updatedAt: 10, docVersion: currentDocVersion),
      v2.DocsData(id: 'i1', tripId: 't1', type: 'item', json: '{"id":"i1"}', updatedAt: 20, docVersion: currentDocVersion),
    ];

    await verifier.testWithDataIntegrity(
      oldVersion: 1,
      newVersion: 2,
      createOld: v1.DatabaseAtV1.new,
      createNew: v2.DatabaseAtV2.new,
      openTestedDatabase: AppDatabase.new,
      createItems: (batch, oldDb) {
        batch.insertAll(oldDb.docs, oldDocsData);
      },
      validateItems: (newDb) async {
        expect(await newDb.select(newDb.docs).get(), expectedNewDocsData);
      },
    );
  });

  test('a database file written by the v1 app opens and loads with the current code', () async {
    final tmp = await Directory.systemTemp.createTemp('tp_migration');
    addTearDown(() => tmp.delete(recursive: true));
    final file = File('${tmp.path}/travel_planner.sqlite');

    // Exactly what the v1 app created (onCreate including the hand-made
    // index), filled through the current repository code and then turned
    // back into a v1 file.
    final demo = demoInterrail();
    final seed = Repository(AppDatabase(NativeDatabase(file)), AttachmentStore(tmp));
    await seed.putTripData(demo);
    final rows = await seed.db.select(seed.db.docs).get();
    await seed.close();
    await file.delete();
    final raw = NativeDatabase(file, setup: (db) {
      db.execute('CREATE TABLE IF NOT EXISTS "docs" ("id" TEXT NOT NULL, "trip_id" TEXT NOT NULL, '
          '"type" TEXT NOT NULL, "json" TEXT NOT NULL, "updated_at" INTEGER NOT NULL, PRIMARY KEY ("id"));');
      db.execute('CREATE INDEX IF NOT EXISTS docs_trip ON docs (trip_id)');
      for (final r in rows) {
        db.execute('INSERT INTO docs VALUES (?, ?, ?, ?, ?)', [r.id, r.tripId, r.type, r.json, r.updatedAt]);
      }
      db.userVersion = 1;
    });
    await raw.ensureOpen(_NoUser());
    await raw.close();

    final repo = Repository(AppDatabase(NativeDatabase(file)), AttachmentStore(tmp));
    addTearDown(repo.close);
    final loaded = (await repo.loadTrip(demo.trip.id))!;
    expect(loaded.trip.title, demo.trip.title);
    expect(loaded.items.length, demo.items.length);
    expect(loaded.cards.length, demo.cards.length);
    expect(loaded.edges.length, demo.edges.length);
    final versions = await repo.db.customSelect('PRAGMA user_version').getSingle();
    expect(versions.read<int>('user_version'), 2);
    expect((await repo.db.select(repo.db.docs).get()).map((r) => r.docVersion).toSet(), {currentDocVersion});
    final fk = await repo.db.customSelect('PRAGMA foreign_keys').getSingle();
    expect(fk.read<int>('foreign_keys'), 1);
  });

  test('migrateDocs rewrites older rows once and leaves current ones alone', () async {
    final db = AppDatabase(NativeDatabase.memory());
    addTearDown(db.close);
    await db.into(db.docs).insert(DocsCompanion.insert(
        id: 'old', tripId: 't', type: 'item', json: jsonEncode({'name': 'Rom'}), updatedAt: 1));
    await db.into(db.docs).insert(DocsCompanion.insert(
        id: 'new',
        tripId: 't',
        type: 'item',
        json: jsonEncode({'title': 'Paris'}),
        updatedAt: 1,
        docVersion: const Value(2)));
    var calls = 0;
    Map<String, Object?> rename(String type, Map<String, Object?> j) {
      calls++;
      final copy = {...j};
      return copy..['title'] = copy.remove('name');
    }

    await db.migrateDocs(to: 2, steps: [rename]);
    await db.migrateDocs(to: 2, steps: [rename]);
    final rows = {for (final r in await db.select(db.docs).get()) r.id: r};
    expect(calls, 1);
    expect(jsonDecode(rows['old']!.json), {'title': 'Rom'});
    expect(rows['old']!.docVersion, 2);
    expect(jsonDecode(rows['new']!.json), {'title': 'Paris'});
  });
}

class _NoUser extends QueryExecutorUser {
  @override
  int get schemaVersion => 1;

  @override
  Future<void> beforeOpen(QueryExecutor executor, OpeningDetails details) async {}
}
